def 가장큰(가, 나, 다):
    if 가 >= 나 and 가 >= 다:
        return 가
    if 나 >= 다:
        return 나
    return 다

print(가장큰(3, 9, 5))
print(가장큰(8, 2, 5))
print(가장큰(1, 4, 7))

def 자릿수합(수):
    합 = 0
    while 수 > 0:
        합 += 수 % 10
        수 = 수 // 10
    return 합

for i in range(1, 101):
    if 자릿수합(i) == 10:
        print(i)

def 약수합(수):
    합 = 0
    for i in range(1, 수):
        if 수 % i == 0:
            합 += i
    return 합

for 수 in range(1, 101):
    if 약수합(수) == 수:
        print(수)
